export function createRoom(templateId = 'library') {
  const t = templates.find((t) => t.id === templateId) || templates[0];
  const early = t.id === 'early';
  const people = Array.from({ length: t.count }, (_, i) => {
    const group = GROUPS[i % GROUPS.length];
    let arrive = early ? 450 + (i % 5) * 30 : 810 + (i % 7) * 35 + (i % 3) * 10;
    let leaveBy = early ? 660 + (i % 4) * 30 : 1120 + (i % 5) * 25;
    return {
      id: uid(),
      name: names[i % names.length],
      group,
      arrive,
      leaveBy,
      duration: [45, 60, 75, 90][i % 4],
      travelIn: [10, 15, 20, 0][i % 4],
      travelOut: [10, 15, 20, 25][i % 4],
      days: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'],
      weight: [1, 2, 1, 3, 2, 1][i % 6],
      priority: i % 6 === 0 ? 2 : 0,
      transit: i % 3 !== 0,
      computer: i % 4 < 2,
      wifi: i % 4 < 2,
      access: i % 9 === 0,
      child: group === 'Caregivers',
      quiet: i % 7 === 0,
      source: 'Illustrative profile',
      note: [
        'Preparing for exams',
        'Completing an application',
        'Accessing online services',
        'Working around a shift',
        'Reading and learning',
        'Connecting with family',
      ][i % 6],
    };
  });
  return {
    id: uid(),
    title: t.title,
    template: t.id,
    location: 'Illustrative community',
    description: t.description,
    demo: true,
    people,
    baseline: { ...DEFAULT_POLICY, ...t.baseline },
    policy: { ...DEFAULT_POLICY, ...t.baseline, ...t.policy },
    scenarios: [],
    evidence: [
      {
        id: uid(),
        title: 'Illustrative dataset',
        kind: 'Assumption',
        detail:
          'These are fictional aliases and constraints designed to demonstrate the model. They are not survey results or a claim about a real community.',
        date: new Date().toISOString().slice(0, 10),
        url: '',
        confidence: 'Illustrative',
      },
    ],
    notes: [],
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
}
